module oil_cans (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] start_energy,\n    input wire [1:0] start_x,\n    input wire [1:0] start_y,\n    input wire [1:0] can_x0, input wire [1:0] can_y0,\n    input wire [4:0] can_t0, input wire can_valid0,\n    input wire [1:0] can_x1, input wire [1:0] can_y1,\n    input wire [4:0] can_t1, input wire can_valid1,\n    input wire [1:0] can_x2, input wire [1:0] can_y2,\n    input wire [4:0] can_t2, input wire can_valid2,\n    input wire [1:0] can_x3, input wire [1:0] can_y3,\n    input wire [4:0] can_t3, input wire can_valid3,\n    input wire [1:0] can_x4, input wire [1:0] can_y4,\n    input wire [4:0] can_t4, input wire can_valid4,\n    input wire [1:0] can_x5, input wire [1:0] can_y5,\n    input wire [4:0] can_t5, input wire can_valid5,\n    input wire [1:0] can_x6, input wire [1:0] can_y6,\n    input wire [4:0] can_t6, input wire can_valid6,\n    input wire [1:0] can_x7, input wire [1:0] can_y7,\n    input wire [4:0] can_t7, input wire can_valid7,\n    output reg [3:0] max_points,\n    output reg done\n);\n\n    // FSM states\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] LOAD         = 3'd1;\n    localparam [2:0] COMPUTE_INIT = 3'd2;\n    localparam [2:0] PRECOMPUTE   = 3'd3;\n    localparam [2:0] UPDATE_STATE = 3'd4;\n    localparam [2:0] MAX_STATE    = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [4:0] time_step;\n    reg [7:0] cycle_counter;\n    reg [3:0] max_value;\n    reg [2:0] load_counter;\n\n    // Array declarations\n    reg [3:0] can_count [0:20][0:3][0:3];  // [time][x][y]\n    reg [3:0] dp_current [0:10][0:3][0:3];\n    reg [3:0] dp_next [0:10][0:3][0:3];\n    reg [3:0] points_gain_table [0:3][0:3];\n    reg [3:0] energy_gain_table [0:3][0:3];\n\n    // Combinational next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE:         if (start) next_state = LOAD;\n            LOAD:         if (load_counter == 3'd7) next_state = COMPUTE_INIT;\n            COMPUTE_INIT: next_state = PRECOMPUTE;\n            PRECOMPUTE:   if (cycle_counter >= 8'd191) next_state = UPDATE_STATE;\n            UPDATE_STATE: if (cycle_counter >= 8'd175) next_state = (time_step == 5'd19) ? MAX_STATE : PRECOMPUTE;\n            MAX_STATE:    if (cycle_counter >= 8'd175) next_state = IDLE;\n            default:      next_state = IDLE;\n        endcase\n    end\n\n    // Sequential logic\n    integer i, j, k, t, e;  // Loop variables\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            max_points <= 4'd0;\n            time_step <= 5'd0;\n            cycle_counter <= 8'd0;\n            load_counter <= 3'd0;\n            max_value <= 4'd0;\n\n            // Initialize can_count\n            for (t = 0; t <= 20; t = t + 1) begin\n                for (i = 0; i < 4; i = i + 1) begin\n                    for (j = 0; j < 4; j = j + 1) begin\n                        can_count[t][i][j] <= 4'd0;\n                    end\n                end\n            end\n\n            // Initialize DP tables\n            for (e = 0; e <= 10; e = e + 1) begin\n                for (i = 0; i < 4; i = i + 1) begin\n                    for (j = 0; j < 4; j = j + 1) begin\n                        dp_current[e][i][j] <= 4'd15;  // Unreachable\n                        dp_next[e][i][j] <= 4'd15;\n                    end\n                end\n            end\n        end\n        else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        load_counter <= 3'd0;\n                        cycle_counter <= 8'd0;\n                    end\n                end\n\n                LOAD: begin\n                    case (load_counter)\n                        3'd0: if (can_valid0) can_count[can_t0][can_x0][can_y0] <= can_count[can_t0][can_x0][can_y0] + 4'd1;\n                        3'd1: if (can_valid1) can_count[can_t1][can_x1][can_y1] <= can_count[can_t1][can_x1][can_y1] + 4'd1;\n                        3'd2: if (can_valid2) can_count[can_t2][can_x2][can_y2] <= can_count[can_t2][can_x2][can_y2] + 4'd1;\n                        3'd3: if (can_valid3) can_count[can_t3][can_x3][can_y3] <= can_count[can_t3][can_x3][can_y3] + 4'd1;\n                        3'd4: if (can_valid4) can_count[can_t4][can_x4][can_y4] <= can_count[can_t4][can_x4][can_y4] + 4'd1;\n                        3'd5: if (can_valid5) can_count[can_t5][can_x5][can_y5] <= can_count[can_t5][can_x5][can_y5] + 4'd1;\n                        3'd6: if (can_valid6) can_count[can_t6][can_x6][can_y6] <= can_count[can_t6][can_x6][can_y6] + 4'd1;\n                        3'd7: if (can_valid7) can_count[can_t7][can_x7][can_y7] <= can_count[can_t7][can_x7][can_y7] + 4'd1;\n                    endcase\n                    load_counter <= load_counter + 3'd1;\n                end\n\n                COMPUTE_INIT: begin\n                    // Clear DP tables\n                    for (e = 0; e <= 10; e = e + 1) begin\n                        for (i = 0; i < 4; i = i + 1) begin\n                            for (j = 0; j < 4; j = j + 1) begin\n                                dp_current[e][i][j] <= (e == start_energy && i == start_x && j == start_y) ? 4'd0 : 4'd15;\n                            end\n                        end\n                    end\n                    cycle_counter <= 8'd0;\n                    time_step <= 5'd0;\n                end\n\n                PRECOMPUTE: begin\n                    cycle_counter <= cycle_counter + 8'd1;\n                    if (cycle_counter < 8'd176) begin\n                        // Initialize dp_next\n                        for (e = 0; e <= 10; e = e + 1) begin\n                            for (i = 0; i < 4; i = i + 1) begin\n                                for (j = 0; j < 4; j = j + 1) begin\n                                    dp_next[e][i][j] <= 4'd15;\n                                end\n                            end\n                        end\n                    end\n                    else if (cycle_counter < 8'd192) begin\n                        // Compute gain tables\n                        i = (cycle_counter - 8'd176) / 4;\n                        j = (cycle_counter - 8'd176) % 4;\n                        points_gain_table[i][j] <= can_count[time_step + 5'd1][i][j];\n                        energy_gain_table[i][j] <= (i<3 ? can_count[time_step + 5'd1][i+1][j] : 4'd0) +\n                                                  (i>0 ? can_count[time_step + 5'd1][i-1][j] : 4'd0) +\n                                                  (j<3 ? can_count[time_step + 5'd1][i][j+1] : 4'd0) +\n                                                  (j>0 ? can_count[time_step + 5'd1][i][j-1] : 4'd0);\n                    end\n                end\n\n                UPDATE_STATE: begin\n                    cycle_counter <= cycle_counter + 8'd1;\n                    if (cycle_counter < 8'd176) begin\n                        e = cycle_counter[7:4];  // Upper bits for energy\n                        i = cycle_counter[3:2];  // Middle bits for x\n                        j = cycle_counter[1:0];  // Lower bits for y\n\n                        if (dp_current[e][i][j] != 4'd15 && e <= 10) begin\n                            // Stay in place\n                            if (e + energy_gain_table[i][j] <= 10) begin\n                                if (dp_next[e + energy_gain_table[i][j]][i][j] < dp_current[e][i][j] + points_gain_table[i][j])}\n